Arguments:
$ErrorActionPreference='Stop'
$llvm='C:\Program Files\LLVM\bin\llvm-objdump.exe'
$obj='benchmarks/SomeEngine.ECS.Relations.Benchmarks/obj/Release/net10.0/win-x64/native/SomeEngine.ECS.Relations.Benchmarks.obj'
$symbols=@(& $llvm -t $obj)
if($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$targets=@(foreach($line in $symbols) { if($line -match '\(sec\s+2\).* 0x[0-9a-f]+ (.+)$') { $symbol=$Matches[1]; if($symbol -match 'World__ExecuteQueryAdmitted<.*SingleExecution_1<.*KeyPairs_5<.*KeyPairsWithin.*SameCharacterHair.*QueryIdentityOutput_2<.*SpatialPairOutput') { $symbol } } })
Write-Output ('SELECTED '+$targets.Count)
$targets | ForEach-Object {Write-Output ('TARGET '+$_)}
if($targets.Count -eq 1) { & $llvm -d -r ('--disassemble-symbols='+$targets[0]) $obj; exit $LASTEXITCODE }
exit 1
